};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { TOP_500_EN } from '../data/speedWords';
import { soundEngine } from '../utils/soundEngine';
import { Timer, Zap, RotateCcw, X, Trophy, AlertCircle, Target, Brain, Activity } from 'lucide-react';

interface WordStat {
    mistakes: number;
    totalTyped: number;
    avgCps: number; // Characters per second
    lastSeen: number;
}

interface SpeedSprintProps {
  onComplete: (xp: number, wpm: number, mistakes: string[]) => void;
  onFail: () => void;
  onExit: () => void;
}

const SpeedSprint: React.FC<SpeedSprintProps> = ({ onComplete, onFail, onExit }) => {
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'RESULT' | 'FAILED'>('IDLE');
  const [words, setWords] = useState<string[]>([]);
  const [input, setInput] = useState('');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(60);
  const [startTime, setStartTime] = useState<number | null>(null);
  const [correctKeystrokes, setCorrectKeystrokes] = useState(0);
  const [priorityCount, setPriorityCount] = useState(0);

  // Per-word timing for mastery tracking
  const wordStartTimeRef = useRef<number>(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const timerRef = useRef<number | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Load word stats from localStorage
  const getWordStats = useCallback((): Record<string, WordStat> => {
      const saved = localStorage.getItem('frogType_speedMastery');
      return saved ? JSON.parse(saved) : {};
  }, []);

  const saveWordStats = useCallback((stats: Record<string, WordStat>) => {
      localStorage.setItem('frogType_speedMastery', JSON.stringify(stats));
  }, []);

  const updateWordStat = useCallback((word: string, isMistake: boolean, cps: number = 0) => {
      const stats = getWordStats();
      if (!stats[word]) {
          stats[word] = { mistakes: 0, totalTyped: 0, avgCps: 0, lastSeen: Date.now() };
      }

      const s = stats[word];
      s.totalTyped += 1;
      s.lastSeen = Date.now();

      if (isMistake) {
          s.mistakes += 1;
      } else if (cps > 0) {
          // Moving average for CPS
          s.avgCps = s.avgCps === 0 ? cps : (s.avgCps * 0.7) + (cps * 0.3);
      }

      saveWordStats(stats);
  }, [getWordStats, saveWordStats]);

  const generateWords = useCallback(() => {
    const stats = getWordStats();
    const globalAvgCps = Object.values(stats).reduce((acc, s) => acc + s.avgCps, 0) / (Object.keys(stats).length || 1);

    // Identify words that need work: 
    // 1. High mistake count
    // 2. Slow CPS (below 80% of average)
    // 3. Never seen
    const weakWords = TOP_500_EN.filter(w => {
        const s = stats[w];
        if (!s) return true; // New words are priority
        if (s.mistakes > 0) return true;
        if (s.avgCps > 0 && s.avgCps < globalAvgCps * 0.8) return true;
        return false;
    });

    let pool: string[] = [];
    let pCount = 0;

    // Build adaptive list
    // 60% Priority words, 40% Random from the rest
    const remainingWords = TOP_500_EN.filter(w => !weakWords.includes(w));

    for (let i = 0; i < 200; i++) {
        if (weakWords.length > 0 && Math.random() < 0.6) {
            pool.push(weakWords[Math.floor(Math.random() * weakWords.length)]);
            pCount++;
        } else {
            const source = remainingWords.length > 0 ? remainingWords : TOP_500_EN;
            pool.push(source[Math.floor(Math.random() * source.length)]);
        }
    }

    setPriorityCount(pCount);
    return pool;
  }, [getWordStats]);

  const initGame = useCallback(() => {
    setWords(generateWords());
    setCurrentIndex(0);
    setInput('');
    setTimeLeft(60);
    setGameState('IDLE');
    setStartTime(null);
    setCorrectKeystrokes(0);
    if (timerRef.current) clearInterval(timerRef.current);
  }, [generateWords]);

  useEffect(() => {
    initGame();
  }, [initGame]);

  const startTimer = () => {
    setStartTime(Date.now());
    wordStartTimeRef.current = performance.now();
    setGameState('PLAYING');
    timerRef.current = window.setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          finishGame();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  const finishGame = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    setGameState('RESULT');
    const finalWpm = Math.round((correctKeystrokes / 5)); 
    const xp = Math.floor(finalWpm * 3); // Slightly higher XP for mastery mode
    onComplete(xp, finalWpm, []);
  };

  const failGame = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    const failedWord = words[currentIndex];
    updateWordStat(failedWord, true); // Mark as mistake
    setGameState('FAILED');
    soundEngine.playError();
    onFail();
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (gameState === 'RESULT' || gameState === 'FAILED') return;

    const val = e.target.value;
    if (gameState === 'IDLE' && val.length > 0) {
      startTimer();
    }

    const currentWord = words[currentIndex];

    if (val.endsWith(' ')) {
      const typedWord = val.trim();
      if (typedWord === currentWord) {
        soundEngine.playSuccess();

        // Calculate CPS for this word
        const now = performance.now();
        const duration = (now - wordStartTimeRef.current) / 1000;
        const cps = currentWord.length / duration;
        updateWordStat(currentWord, false, cps);

        setCorrectKeystrokes(prev => prev + currentWord.length + 1);
        setCurrentIndex(prev => prev + 1);
        setInput('');
        wordStartTimeRef.current = performance.now(); // Reset for next word

        if (scrollRef.current) {
            const activeEl = scrollRef.current.querySelector(`[data-word-index="${currentIndex + 1}"]`);
            if (activeEl) {
                activeEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
      } else {
        failGame();
      }
      return;
    }

    if (currentWord.startsWith(val)) {
      setInput(val);
      soundEngine.playKeypress();
    } else {
      failGame();
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Adaptive HUD */}
      <div className="flex items-center justify-between bg-white/50 backdrop-blur-md p-6 rounded-3xl border border-stone-200 shadow-sm">
          <div className="flex items-center gap-6">
              <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-1">Time Left</span>
                  <div className={`text-4xl font-black font-mono transition-colors ${timeLeft < 10 ? 'text-red-500 animate-pulse' : 'text-stone-800'}`}>
                      {timeLeft}s
                  </div>
              </div>
              <div className="w-px h-10 bg-stone-200"></div>
              <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-1">Focus Engine</span>
                  <div className="flex items-center gap-2 text-purple-600 font-bold">
                      <Brain className="w-4 h-4" /> {priorityCount} Mastery Words
                  </div>
              </div>
              <div className="w-px h-10 bg-stone-200"></div>
              <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-1">Status</span>
                  <div className="flex items-center gap-2 text-frog-green font-bold">
                      <Activity className="w-4 h-4" /> Live Tracking
                  </div>
              </div>
          </div>

          <button 
            onClick={onExit}
            className="p-3 text-stone-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-all"
          >
              <X className="w-6 h-6" />
          </button>
      </div>

      {/* Adaptive Word Cloud */}
      <div className="relative">
          <div 
            ref={scrollRef}
            className={`
                bg-white p-10 rounded-[2.5rem] border-2 border-stone-100 shadow-xl h-64 overflow-hidden relative flex flex-wrap gap-x-4 gap-y-4 items-center justify-center content-start transition-all
                ${gameState === 'FAILED' ? 'bg-red-50 border-red-200 opacity-50' : ''}
            `}
          >
              {words.slice(Math.max(0, currentIndex - 20), currentIndex + 50).map((word, i) => {
                  const absoluteIndex = Math.max(0, currentIndex - 20) + i;
                  const isCurrent = absoluteIndex === currentIndex;
                  const isPast = absoluteIndex < currentIndex;

                  return (
                      <span 
                        key={`${word}-${absoluteIndex}`}
                        data-word-index={absoluteIndex}
                        className={`
                            text-2xl font-mono transition-all duration-300 px-2 py-1 rounded-lg
                            ${isCurrent ? 'bg-frog-green text-white font-black scale-110 shadow-lg shadow-frog-green/20 z-10' : ''}
                            ${isPast ? 'text-stone-200 opacity-30' : 'text-stone-400'}
                        `}
                      >
                          {word}
                      </span>
                  );
              })}

              {gameState === 'IDLE' && (
                  <div className="absolute inset-0 bg-stone-900/5 backdrop-blur-[2px] flex items-center justify-center z-20 cursor-text" onClick={() => inputRef.current?.focus()}>
                      <div className="text-center animate-bounce">
                          <Zap className="w-12 h-12 text-frog-green mx-auto mb-2" fill="currentColor" />
                          <span className="text-stone-800 font-black text-xl uppercase tracking-widest">Type to start adaptive sprint</span>
                      </div>
                  </div>
              )}
          </div>
      </div>

      <input 
        ref={inputRef}
        type="text"
        value={input}
        onChange={handleInputChange}
        className="opacity-0 absolute -z-10"
        autoFocus
        autoComplete="off"
        autoCorrect="off"
        autoCapitalize="off"
        spellCheck="false"
      />

      {/* Result Modals */}
      {gameState === 'RESULT' && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-stone-900/20 backdrop-blur-md animate-in fade-in duration-300">
              <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-stone-100 flex flex-col items-center gap-8 max-w-md w-full">
                  <div className="flex flex-col items-center">
                      <Trophy className="w-16 h-16 text-yellow-500 mb-2" />
                      <h2 className="text-3xl font-black text-stone-800 tracking-tight">Sprint Mastered!</h2>
                      <p className="text-stone-400 font-medium text-sm text-center">Adaptive engine updated. Your weak points are being reinforced.</p>
                  </div>

                  <div className="grid grid-cols-2 gap-8 w-full">
                      <div className="text-center">
                          <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest">Speed</span>
                          <div className="text-4xl font-black text-frog-green">{Math.round(correctKeystrokes/5)} <span className="text-xs">WPM</span></div>
                      </div>
                      <div className="text-center">
                          <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest">XP Earned</span>
                          <div className="text-4xl font-black text-stone-800">+{Math.floor(correctKeystrokes/2)}</div>
                      </div>
                  </div>

                  <div className="flex gap-4 w-full">
                      <button onClick={onExit} className="flex-1 py-4 bg-stone-100 hover:bg-stone-200 text-stone-600 font-black rounded-2xl transition-all">EXIT</button>
                      <button onClick={initGame} className="flex-1 py-4 bg-frog-green hover:bg-green-500 text-white font-black rounded-2xl shadow-lg shadow-frog-green/30 transition-all flex items-center justify-center gap-2">
                        <RotateCcw className="w-4 h-4" /> RE-CALIBRATE
                      </button>
                  </div>
              </div>
          </div>
      )}

      {gameState === 'FAILED' && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-stone-900/20 backdrop-blur-md animate-in fade-in duration-300">
              <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-red-100 flex flex-col items-center gap-8 max-w-md w-full">
                  <div className="flex flex-col items-center">
                      <AlertCircle className="w-16 h-16 text-red-500 mb-2" />
                      <h2 className="text-3xl font-black text-stone-800 tracking-tight">Focus Lost</h2>
                      <p className="text-stone-400 font-medium text-sm text-center">Mistake on <span className="text-red-500 font-bold">"{words[currentIndex]}"</span>. This word will now appear more frequently until mastered.</p>
                  </div>

                  <div className="flex gap-4 w-full">
                      <button onClick={onExit} className="flex-1 py-4 bg-stone-100 hover:bg-stone-200 text-stone-600 font-black rounded-2xl transition-all">EXIT</button>
                      <button onClick={initGame} className="flex-1 py-4 bg-red-500 hover:bg-red-600 text-white font-black rounded-2xl shadow-lg shadow-red-200/30 transition-all flex items-center justify-center gap-2">
                        <RotateCcw className="w-4 h-4" /> RETRY TARGET
                      </button>
                  </div>
              </div>
          </div>
      )}

      <div className="text-center text-stone-400 text-xs font-medium animate-pulse">
          100% Accuracy Required. Mistyped words are automatically added to your priority training list.
      </div>
    </div>
  );
};

export default SpeedSprint;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { TOP_500_EN } from '../data/speedWords';
import { soundEngine } from '../utils/soundEngine';
import { Timer, Zap, RotateCcw, X, Trophy, AlertCircle, Target, Brain, Activity } from 'lucide-react';

interface WordStat {
    mistakes: number;
    totalTyped: number;
    avgCps: number; // Characters per second
    lastSeen: number;
}

interface SpeedSprintProps {
  onComplete: (xp: number, wpm: number, mistakes: string[]) => void;
  onFail: () => void;
  onExit: () => void;
}

const SpeedSprint: React.FC<SpeedSprintProps> = ({ onComplete, onFail, onExit }) => {
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'RESULT' | 'FAILED'>('IDLE');
  const [words, setWords] = useState<string[]>([]);
  const [input, setInput] = useState('');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(60);
  const [startTime, setStartTime] = useState<number | null>(null);
  const [correctKeystrokes, setCorrectKeystrokes] = useState(0);
  const [priorityCount, setPriorityCount] = useState(0);

  // Per-word timing for mastery tracking
  const wordStartTimeRef = useRef<number>(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const timerRef = useRef<number | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Load word stats from localStorage
  const getWordStats = useCallback((): Record<string, WordStat> => {
      const saved = localStorage.getItem('frogType_speedMastery');
      return saved ? JSON.parse(saved) : {};
  }, []);

  const saveWordStats = useCallback((stats: Record<string, WordStat>) => {
      localStorage.setItem('frogType_speedMastery', JSON.stringify(stats));
  }, []);

  const updateWordStat = useCallback((word: string, isMistake: boolean, cps: number = 0) => {
      const stats = getWordStats();
      if (!stats[word]) {
          stats[word] = { mistakes: 0, totalTyped: 0, avgCps: 0, lastSeen: Date.now() };
      }

      const s = stats[word];
      s.totalTyped += 1;
      s.lastSeen = Date.now();

      if (isMistake) {
          s.mistakes += 1;
      } else if (cps > 0) {
          // Moving average for CPS
          s.avgCps = s.avgCps === 0 ? cps : (s.avgCps * 0.7) + (cps * 0.3);
      }

      saveWordStats(stats);
  }, [getWordStats, saveWordStats]);

  const generateWords = useCallback(() => {
    const stats = getWordStats();
    // Fix: Added explicit typing to reduce to fix arithmetic operation and unknown type errors on line 68
    const globalAvgCps = Object.values(stats).reduce((acc: number, s: any) => acc + (s as WordStat).avgCps, 0) / (Object.keys(stats).length || 1);

    // Identify words that need work: 
    // 1. High mistake count
    // 2. Slow CPS (below 80% of average)
    // 3. Never seen
    const weakWords = TOP_500_EN.filter(w => {
        const s = stats[w];
        if (!s) return true; // New words are priority
        if (s.mistakes > 0) return true;
        if (s.avgCps > 0 && s.avgCps < globalAvgCps * 0.8) return true;
        return false;
    });

    let pool: string[] = [];
    let pCount = 0;

    // Build adaptive list
    // 60% Priority words, 40% Random from the rest
    const remainingWords = TOP_500_EN.filter(w => !weakWords.includes(w));

    for (let i = 0; i < 200; i++) {
        if (weakWords.length > 0 && Math.random() < 0.6) {
            pool.push(weakWords[Math.floor(Math.random() * weakWords.length)]);
            pCount++;
        } else {
            const source = remainingWords.length > 0 ? remainingWords : TOP_500_EN;
            pool.push(source[Math.floor(Math.random() * source.length)]);
        }
    }

    setPriorityCount(pCount);
    return pool;
  }, [getWordStats]);

  const initGame = useCallback(() => {
    setWords(generateWords());
    setCurrentIndex(0);
    setInput('');
    setTimeLeft(60);
    setGameState('IDLE');
    setStartTime(null);
    setCorrectKeystrokes(0);
    if (timerRef.current) clearInterval(timerRef.current);
  }, [generateWords]);

  useEffect(() => {
    initGame();
  }, [initGame]);

  const startTimer = () => {
    setStartTime(Date.now());
    wordStartTimeRef.current = performance.now();
    setGameState('PLAYING');
    timerRef.current = window.setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          finishGame();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  const finishGame = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    setGameState('RESULT');
    const finalWpm = Math.round((correctKeystrokes / 5)); 
    const xp = Math.floor(finalWpm * 3); // Slightly higher XP for mastery mode
    onComplete(xp, finalWpm, []);
  };

  const failGame = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    const failedWord = words[currentIndex];
    updateWordStat(failedWord, true); // Mark as mistake
    setGameState('FAILED');
    soundEngine.playError();
    onFail();
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (gameState === 'RESULT' || gameState === 'FAILED') return;

    const val = e.target.value;
    if (gameState === 'IDLE' && val.length > 0) {
      startTimer();
    }

    const currentWord = words[currentIndex];

    if (val.endsWith(' ')) {
      const typedWord = val.trim();
      if (typedWord === currentWord) {
        soundEngine.playSuccess();

        // Calculate CPS for this word
        const now = performance.now();
        const duration = (now - wordStartTimeRef.current) / 1000;
        const cps = currentWord.length / duration;
        updateWordStat(currentWord, false, cps);

        setCorrectKeystrokes(prev => prev + currentWord.length + 1);
        setCurrentIndex(prev => prev + 1);
        setInput('');
        wordStartTimeRef.current = performance.now(); // Reset for next word

        if (scrollRef.current) {
            const activeEl = scrollRef.current.querySelector(`[data-word-index="${currentIndex + 1}"]`);
            if (activeEl) {
                activeEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
      } else {
        failGame();
      }
      return;
    }

    if (currentWord.startsWith(val)) {
      setInput(val);
      soundEngine.playKeypress();
    } else {
      failGame();
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Adaptive HUD */}
      <div className="flex items-center justify-between bg-white/50 backdrop-blur-md p-6 rounded-3xl border border-stone-200 shadow-sm">
          <div className="flex items-center gap-6">
              <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-1">Time Left</span>
                  <div className={`text-4xl font-black font-mono transition-colors ${timeLeft < 10 ? 'text-red-500 animate-pulse' : 'text-stone-800'}`}>
                      {timeLeft}s
                  </div>
              </div>
              <div className="w-px h-10 bg-stone-200"></div>
              <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-1">Focus Engine</span>
                  <div className="flex items-center gap-2 text-purple-600 font-bold">
                      <Brain className="w-4 h-4" /> {priorityCount} Mastery Words
                  </div>
              </div>
              <div className="w-px h-10 bg-stone-200"></div>
              <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-1">Status</span>
                  <div className="flex items-center gap-2 text-frog-green font-bold">
                      <Activity className="w-4 h-4" /> Live Tracking
                  </div>
              </div>
          </div>

          <button 
            onClick={onExit}
            className="p-3 text-stone-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-all"
          >
              <X className="w-6 h-6" />
          </button>
      </div>

      {/* Adaptive Word Cloud */}
      <div className="relative">
          <div 
            ref={scrollRef}
            className={`
                bg-white p-10 rounded-[2.5rem] border-2 border-stone-100 shadow-xl h-64 overflow-hidden relative flex flex-wrap gap-x-4 gap-y-4 items-center justify-center content-start transition-all
                ${gameState === 'FAILED' ? 'bg-red-50 border-red-200 opacity-50' : ''}
            `}
          >
              {words.slice(Math.max(0, currentIndex - 20), currentIndex + 50).map((word, i) => {
                  const absoluteIndex = Math.max(0, currentIndex - 20) + i;
                  const isCurrent = absoluteIndex === currentIndex;
                  const isPast = absoluteIndex < currentIndex;

                  return (
                      <span 
                        key={`${word}-${absoluteIndex}`}
                        data-word-index={absoluteIndex}
                        className={`
                            text-2xl font-mono transition-all duration-300 px-2 py-1 rounded-lg
                            ${isCurrent ? 'bg-frog-green text-white font-black scale-110 shadow-lg shadow-frog-green/20 z-10' : ''}
                            ${isPast ? 'text-stone-200 opacity-30' : 'text-stone-400'}
                        `}
                      >
                          {word}
                      </span>
                  );
              })}

              {gameState === 'IDLE' && (
                  <div className="absolute inset-0 bg-stone-900/5 backdrop-blur-[2px] flex items-center justify-center z-20 cursor-text" onClick={() => inputRef.current?.focus()}>
                      <div className="text-center animate-bounce">
                          <Zap className="w-12 h-12 text-frog-green mx-auto mb-2" fill="currentColor" />
                          <span className="text-stone-800 font-black text-xl uppercase tracking-widest">Type to start adaptive sprint</span>
                      </div>
                  </div>
              )}
          </div>
      </div>

      <input 
        ref={inputRef}
        type="text"
        value={input}
        onChange={handleInputChange}
        className="opacity-0 absolute -z-10"
        autoFocus
        autoComplete="off"
        autoCorrect="off"
        autoCapitalize="off"
        spellCheck="false"
      />

      {/* Result Modals */}
      {gameState === 'RESULT' && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-stone-900/20 backdrop-blur-md animate-in fade-in duration-300">
              <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-stone-100 flex flex-col items-center gap-8 max-w-md w-full">
                  <div className="flex flex-col items-center">
                      <Trophy className="w-16 h-16 text-yellow-500 mb-2" />
                      <h2 className="text-3xl font-black text-stone-800 tracking-tight">Sprint Mastered!</h2>
                      <p className="text-stone-400 font-medium text-sm text-center">Adaptive engine updated. Your weak points are being reinforced.</p>
                  </div>

                  <div className="grid grid-cols-2 gap-8 w-full">
                      <div className="text-center">
                          <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest">Speed</span>
                          <div className="text-4xl font-black text-frog-green">{Math.round(correctKeystrokes/5)} <span className="text-xs">WPM</span></div>
                      </div>
                      <div className="text-center">
                          <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest">XP Earned</span>
                          <div className="text-4xl font-black text-stone-800">+{Math.floor(correctKeystrokes/2)}</div>
                      </div>
                  </div>

                  <div className="flex gap-4 w-full">
                      <button onClick={onExit} className="flex-1 py-4 bg-stone-100 hover:bg-stone-200 text-stone-600 font-black rounded-2xl transition-all">EXIT</button>
                      <button onClick={initGame} className="flex-1 py-4 bg-frog-green hover:bg-green-500 text-white font-black rounded-2xl shadow-lg shadow-frog-green/30 transition-all flex items-center justify-center gap-2">
                        <RotateCcw className="w-4 h-4" /> RE-CALIBRATE
                      </button>
                  </div>
              </div>
          </div>
      )}

      {gameState === 'FAILED' && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-stone-900/20 backdrop-blur-md animate-in fade-in duration-300">
              <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-red-100 flex flex-col items-center gap-8 max-w-md w-full">
                  <div className="flex flex-col items-center">
                      <AlertCircle className="w-16 h-16 text-red-500 mb-2" />
                      <h2 className="text-3xl font-black text-stone-800 tracking-tight">Focus Lost</h2>
                      <p className="text-stone-400 font-medium text-sm text-center">Mistake on <span className="text-red-500 font-bold">"{words[currentIndex]}"</span>. This word will now appear more frequently until mastered.</p>
                  </div>

                  <div className="flex gap-4 w-full">
                      <button onClick={onExit} className="flex-1 py-4 bg-stone-100 hover:bg-stone-200 text-stone-600 font-black rounded-2xl transition-all">EXIT</button>
                      <button onClick={initGame} className="flex-1 py-4 bg-red-500 hover:bg-red-600 text-white font-black rounded-2xl shadow-lg shadow-red-200/30 transition-all flex items-center justify-center gap-2">
                        <RotateCcw className="w-4 h-4" /> RETRY TARGET
                      </button>
                  </div>
              </div>
          </div>
      )}

      <div className="text-center text-stone-400 text-xs font-medium animate-pulse">
          100% Accuracy Required. Mistyped words are automatically added to your priority training list.
      </div>
    </div>
  );
};

export default SpeedSprint;
